/* My Singing Dogs – The Expansion. GitHub Pages, offline-ready, local saves. */
(()=>{'use strict';
const $=id=>document.getElementById(id),audio=window.MSDAudio,SCORE=window.MSD_SCORE;
const icon=n=>`<svg class="ico"><use href="#i-${n}"/></svg>`;
const ISLANDS={plant:{name:'Plant Island',song:'The Green Overture',tag:'Where wild melodies take root',label:'THE FIRST HARMONY',elements:['wind','stone','tech'],unlock:0},ice:{name:'Ice Island',song:'Aurora Nocturne',tag:'An aurora woven out of song',label:'THE FROSTBOUND CONCERTO',elements:['wind','stone','cold'],unlock:25000},wind:{name:'Wind Island',song:'Cloudborne Symphony',tag:'The sky sings with rushing water',label:'THE OPEN SKY',elements:['wind','stone','water'],unlock:65000}};
const SPECS={
wind:{name:'Zephy',els:['Wind'],role:'Airy flute',style:'wind',color:'#9ae6ff',price:350,rate:.58},stone:{name:'Boulder',els:['Stone'],role:'Grounding bass',style:'bass',color:'#ead4ac',price:550,rate:.69},tech:{name:'Bitbit',els:['Tech'],role:'Electric piano',style:'synth',color:'#75e8ef',price:950,rate:.66},cold:{name:'Frostle',els:['Cold'],role:'Warm choir',style:'voice',color:'#a7eaff',price:950,rate:.72},water:{name:'Ripplet',els:['Water'],role:'Liquid strings',style:'harp',color:'#59dfff',price:1300,rate:.78},
windstone:{name:'Gustone',els:['Wind','Stone'],role:'Wooden percussion',style:'drum',color:'#d5cca0',rate:1.34},windtech:{name:'Aerobyte',els:['Wind','Tech'],role:'Analog synthesizer',style:'synth',color:'#83dfff',rate:1.46},stonetech:{name:'Gearruff',els:['Stone','Tech'],role:'Low brass',style:'bass',color:'#ffc98e',rate:1.46},windcold:{name:'Flurruff',els:['Wind','Cold'],role:'Airborne choir',style:'voice',color:'#d2faff',rate:1.42},stonecold:{name:'Cryolith',els:['Stone','Cold'],role:'Expressive cello',style:'voice',color:'#a4cbff',rate:1.48},windwater:{name:'Mistwhirl',els:['Wind','Water'],role:'Ripple harp',style:'harp',color:'#83f5fa',rate:1.49},stonewater:{name:'Riverock',els:['Stone','Water'],role:'Resonant cello',style:'voice',color:'#7ce9da',rate:1.53},
planttriple:{name:'Copperleaf',els:['Wind','Stone','Tech'],role:'Golden horn',style:'voice',color:'#ffdf82',rate:3.4},icetriple:{name:'Glacierhorn',els:['Wind','Stone','Cold'],role:'Winter horn',style:'voice',color:'#b9eaff',rate:3.4},windtriple:{name:'Stormcaller',els:['Wind','Stone','Water'],role:'Storm brass',style:'voice',color:'#9ae7ff',rate:3.8},
plantmyth:{name:'Verdantor',els:['Mythical'],role:'Living pipe organ',style:'voice',color:'#edda80',rate:7.5,myth:true},icemyth:{name:'Auroruff',els:['Mythical'],role:'Celestial harp',style:'harp',color:'#d2aaff',rate:7.5,myth:true},windmyth:{name:'Aetherpaw',els:['Mythical'],role:'Celestial chorus',style:'harp',color:'#d1c2ff',rate:7.8,myth:true},
jinglepup:{name:'Jinglepup',els:['Cold','Seasonal'],role:'Winter bells and choir',style:'voice',color:'#ffcb86',rate:6.6,seasonal:true},
howltron:{name:'Howltron',els:['Legendary'],role:'Mechanical pipe organ',style:'bass',color:'#ffca6e',rate:26,box:true},
luckypaw:{name:'Luckypaw',els:['Wheel-exclusive'],role:'Shimmering keyboards',style:'harp',color:'#ffe27f',rate:4,exclusive:'wheel'},scratchpaw:{name:'Scratchpaw',els:['Ticket-exclusive'],role:'Playful cello',style:'voice',color:'#ffaee7',rate:5,exclusive:'ticket'}};
const BASE={plant:['wind','stone','tech','windstone','windtech','stonetech','planttriple','plantmyth'],ice:['wind','stone','cold','windstone','windcold','stonecold','icetriple','icemyth'],wind:['wind','stone','water','windstone','windwater','stonewater','windtriple','windmyth']};
window.MSD_PREVIEW_KEYS=BASE;
const EXTRA={plant:['howltron','luckypaw','scratchpaw'],ice:['jinglepup','howltron','luckypaw','scratchpaw'],wind:['howltron','luckypaw','scratchpaw']};
const ALL=Object.fromEntries(Object.keys(BASE).map(k=>[k,[...BASE[k],...EXTRA[k]]]));
const KEYWORDS=['wind','stone','tech','cold','windstone','windtech','stonetech','windcold','stonecold','planttriple','icetriple','plantmyth','icemyth','water','windwater','stonewater','windtriple','windmyth','jinglepup','howltron','luckypaw','scratchpaw'];
const SLOTS=[[20,49],[37,47],[54,48],[72,47],[87,49],[19,65],[36,65],[53,65],[70,65],[86,66],[22,80],[39,81],[56,80],[72,81],[88,80],[28,57],[45,57],[63,57],[80,57],[32,74],[48,74],[65,74],[78,74],[20,73]];
const CASTLES=[10,16,24,32,48,64],CASTLE_PRICES=[12000,35000,110000,390000,1450000];
const BAKES=[{name:'Little Loaves',time:600,coins:350,treats:100},{name:'Big Biscuits',time:1800,coins:1600,treats:600},{name:'Royal Bakes',time:3600,coins:6500,treats:2700},{name:'Festival Feast',time:7200,coins:26000,treats:13000}];
const SAVEKEY='my-singing-dogs-v1';
let state,view={panel:null,selected:null,parentA:null,parentB:null},dragging=null,lastTick=Date.now(),lastFrame=0,spinning=false;
const fmt=n=>Math.floor(Math.max(0,Number(n)||0)).toLocaleString('en-US');
const stamp=t=>{t=Math.max(0,Math.round(t));return Math.floor(t/60)+':'+String(t%60).padStart(2,'0')};
const duration=s=>{s=Math.max(0,Math.ceil(s));let h=Math.floor(s/3600),m=Math.floor(s%3600/60),sec=s%60;return h?`${h}h ${m}m ${sec}s`:m?`${m}m ${sec}s`:`${sec}s`};
const spec=t=>SPECS[t],keys=Object.keys(ISLANDS),current=()=>state.island;
const atlas=t=>Math.max(0,KEYWORDS.indexOf(t));
const sprite=(t,rare=false)=>`dog-${rare?'rare-':''}${t}.webp`;
const mouth=t=>`<span class="dog-mouth" aria-hidden="true" style="background-position:${(atlas(t)/(KEYWORDS.length-1)*100).toFixed(5)}% 0"></span>`;
const collectionKey=(i,t,r=false)=>`${i}:${t}:${r?'rare':'common'}`;
const tier=t=>spec(t).box?6:spec(t).seasonal?5:spec(t).myth?4:spec(t).exclusive?3:spec(t).els.length;
function etParts(dt=new Date()){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',hourCycle:'h23',year:'numeric',month:'numeric',day:'numeric',hour:'numeric',weekday:'short'}).formatToParts(dt);return Object.fromEntries(parts.filter(p=>p.type!=='literal').map(p=>[p.type,p.value]))}
function today(){const x=etParts();return `${x.year}-${x.month.padStart(2,'0')}-${x.day.padStart(2,'0')}`}
function seasonalNow(){const x=etParts(),month=+x.month,day=+x.day,h=+x.hour;return month===12&&day>=15&&day<=30||x.weekday==='Thu'&&h>=23||x.weekday==='Fri'&&h<8}
function validType(isl,t){return ALL[isl]?.includes(t)}
function emptyStructures(isl){return {bakeries:isl==='plant'?1:0,jobs:[],torches:0,lit:[],vault:0,monument:0}}
function initial(){const ts=Date.now();return {version:2,coins:800,treats:250,gems:30,xp:0,lastAt:ts,day:today(),daily:{coins:0,feeds:0,hatches:0,claimed:[],wheel:false,ticket:false},island:'plant',unlocked:{plant:true,ice:false,wind:false},castle:{plant:10,ice:10,wind:10},incubators:{plant:null,ice:null,wind:null},structures:Object.fromEntries(keys.map(i=>[i,emptyStructures(i)])),boxes:Object.fromEntries(keys.map(i=>[i,{common:false,rare:false}])),inventory:[],discovered:[],achievements:[],settings:{master:100,music:100,sfx:100,reducedMotion:false},stats:{totalCoins:0,totalHatches:0,totalFeeds:0,totalSpins:0},dogs:[],pendingScratch:null};}
const randID=()=>`d${Date.now().toString(36)}${Math.random().toString(36).slice(2,8)}`;
function validateDog(d){if(!d||!validType(d.island,d.type))return null;return{uid:String(d.uid||randID()).slice(0,40),island:d.island,type:d.type,rare:!!d.rare,level:Math.max(1,Math.min(20,Math.round(+d.level||1))),pending:Math.max(0,Math.min(1e9,+d.pending||0)),muted:!!d.muted,volume:Math.max(0,Math.min(2000,+d.volume||100)),x:Math.max(13,Math.min(91,+d.x||50)),y:Math.max(40,Math.min(86,+d.y||65)),born:+d.born||Date.now()}}
function eggValid(e,i){if(!e||e.island!==i||!validType(i,e.type))return null;return {island:i,type:e.type,rare:!!e.rare,ready:Number(e.ready)||Date.now(),started:Number(e.started)||Date.now(),duration:Math.max(1,Math.min(14400,Number(e.duration)||900))}}
function readSave(){try{const obj=JSON.parse(localStorage.getItem(SAVEKEY));if(!obj||![1,2].includes(obj.version)||!Array.isArray(obj.dogs))return null;const base=initial(),s={...base,...obj};s.version=2;s.dogs=obj.dogs.slice(0,300).map(validateDog).filter(Boolean);s.island=keys.includes(obj.island)?obj.island:'plant';for(const k of ['coins','treats','gems','xp'])s[k]=Math.max(0,Math.min(1e12,Number(obj[k])||0));s.lastAt=Number(obj.lastAt)||Date.now();s.unlocked={...base.unlocked,...obj.unlocked};if(obj.version===1){s.unlocked.ice=true;s.unlocked.wind=false;}
 s.castle={};s.incubators={};s.structures={};s.boxes={};for(const i of keys){let c=Number(obj.castle?.[i])||10;s.castle[i]=obj.version===1?({8:10,12:16,16:24}[c]||10):(CASTLES.includes(c)?c:10);s.incubators[i]=eggValid(obj.incubators?.[i],i);const st=obj.structures?.[i]||{};s.structures[i]={...emptyStructures(i),...st,bakeries:Math.max(0,Math.min(3,Number(st.bakeries??(i==='plant'?1:0)))),jobs:(Array.isArray(st.jobs)?st.jobs:[]).filter(j=>BAKES[j.tier]&&Number.isFinite(Number(j.ready))).slice(0,3),torches:Math.max(0,Math.min(10,+st.torches||0)),lit:(Array.isArray(st.lit)?st.lit:[]).filter(t=>Number.isFinite(+t)).slice(0,10),vault:Math.max(0,Math.min(5,+st.vault||0)),monument:Math.max(0,Math.min(5,+st.monument||0))};s.boxes[i]={...base.boxes[i],...obj.boxes?.[i]};}
 s.discovered=[...new Set((Array.isArray(obj.discovered)?obj.discovered:[]).filter(x=>typeof x==='string').map(x=>x.split(':').length===2?x+':common':x).concat(s.dogs.map(d=>collectionKey(d.island,d.type,d.rare))))].filter(x=>{const [i,t,r]=x.split(':');return validType(i,t)&&['rare','common'].includes(r)});
 s.inventory=(Array.isArray(obj.inventory)?obj.inventory:[]).filter(x=>validType(x.island,x.type)).slice(0,100).map(x=>({island:x.island,type:x.type,rare:!!x.rare}));s.achievements=(Array.isArray(obj.achievements)?obj.achievements:[]).filter(x=>typeof x==='string');s.settings={...base.settings,...obj.settings};for(const k of ['master','music','sfx'])s.settings[k]=Math.max(0,Math.min(2000,Number(s.settings[k])||0));s.stats={...base.stats,...obj.stats};s.daily=obj.day===today()&&obj.daily?{...base.daily,...obj.daily}:base.daily;s.day=today();s.pendingScratch=obj.pendingScratch&&typeof obj.pendingScratch==='object'?obj.pendingScratch:null;return s;}catch(e){console.warn('Save invalid',e);return null}}
function save(){if(!state)return;state.lastAt=Date.now();try{localStorage.setItem(SAVEKEY,JSON.stringify(state))}catch(e){console.warn('Save unavailable',e)}}
function dogsOn(i=current()){return state.dogs.filter(d=>d.island===i)}
function dogBy(id){return state.dogs.find(d=>d.uid===id)}
function level(){return Math.min(80,1+Math.floor(Math.sqrt(state.xp/160)))}
function xp(n){state.xp+=n+(state.structures[current()]?.monument||0)*Math.floor(n*.1)}
function rate(d){return spec(d.type).rate*(d.rare?1.7:1)*(.28)*(1+.13*(d.level-1))*(1+(state.structures[d.island]?.vault||0)*.07)}
function cap(d){return Math.max(300,rate(d)*3600*(10+(state.structures[d.island]?.vault||0)*3))}
function syncEconomy(){if(!state)return;const now=Date.now(),delta=Math.max(0,Math.min(12*3600,(now-lastTick)/1000));for(const d of state.dogs){d.pending=Math.min(cap(d),d.pending+delta*rate(d))}lastTick=now;if(state.day!==today()){state.day=today();state.daily={coins:0,feeds:0,hatches:0,claimed:[],wheel:false,ticket:false}}for(const i of keys){const st=state.structures[i];st.lit=st.lit.filter(t=>t>now).slice(0,st.torches)}}
function sfx(kind='tap'){if(state?.settings.sfx)audio.effect(kind)}
function toast(msg,kind=''){const target=$('toastHost');let d=document.createElement('div');d.className=`toast ${kind}`;d.textContent=msg;target.append(d);while(target.children.length>3)target.firstElementChild.remove();setTimeout(()=>{d.style.opacity='0';setTimeout(()=>d.remove(),250)},3400)}
function reveal(i,t,rare){const host=$('discoveryOverlay');if(!host)return;const isRare=rare?'RARE ':'',isSpecial=spec(t).myth?'MYTHICAL DISCOVERY':spec(t).seasonal?'SEASONAL DISCOVERY':spec(t).exclusive?'EXCLUSIVE DISCOVERY':'NEW DOG DISCOVERED';host.innerHTML=`<div class="discovery-card"><span class="discovery-kicker">${isSpecial}</span><div class="discovery-rays"></div><img src="${sprite(t,rare)}" alt="${isRare+spec(t).name}"><h2>${isRare+spec(t).name}!</h2><p>${ISLANDS[i].name} · ${spec(t).role}</p><button id="dismissDiscovery" class="pill-btn blue">Continue</button></div>`;host.classList.remove('hidden');host.querySelector('button').onclick=()=>host.classList.add('hidden');sfx('egg');}
function addDog(i,t,rare=false,quiet=false){if(!validType(i,t))return null;if(dogsOn(i).length>=state.castle[i])return null;let pos=SLOTS[dogsOn(i).length%SLOTS.length],d={uid:randID(),island:i,type:t,rare:!!rare,level:1,pending:0,muted:false,volume:100,x:pos[0],y:pos[1],born:Date.now()};state.dogs.push(d);const key=collectionKey(i,t,rare),fresh=!state.discovered.includes(key);if(fresh)state.discovered.push(key);if(!quiet){xp(50*tier(t)*(rare?2:1));if(fresh){closePanel();reveal(i,t,rare)}else toast(`${rare?'Rare ':''}${spec(t).name} joined ${ISLANDS[i].name}!`,'good');audio.refreshMix();save();render()}return d}
function grant(i,t,rare=false){if(!state.unlocked[i])state.unlocked[i]=true;let d=addDog(i,t,rare);if(!d){state.inventory.push({island:i,type:t,rare});toast(`${spec(t).name} was safely placed in Storage. Castle full.`,'good')}save();render()}
function dogMix(){const mix={};for(const d of dogsOn())if(!d.muted){mix[d.type]=(mix[d.type]||0)+d.volume/100*(d.rare?1.12:1)}for(const k of Object.keys(mix))mix[k]=Math.min(1.35,mix[k]);return mix}
function start(){state=readSave();if(!state){state=initial();for(const t of ['wind','stone','tech'])addDog('plant',t,false,true);save()}lastTick=state.lastAt;syncEconomy();audio.island=state.island;audio.getMix=dogMix;audio.onState=renderAudio;audio.onError=m=>toast(m,'warn');audio.setVolumes(state.settings.master,state.settings.music)}
function switchIsland(i){if(!keys.includes(i))return;if(!state.unlocked[i]){openPanel('islands');toast(`Unlock ${ISLANDS[i].name} for ${fmt(ISLANDS[i].unlock)} coins.`,'warn');return}if(i===current())return;syncEconomy();state.island=i;view.selected=null;view.parentA=null;view.parentB=null;audio.setIsland(i);render();save();sfx()}
function buyUnlock(i){if(!keys.includes(i)||state.unlocked[i])return;if(state.coins<ISLANDS[i].unlock)return toast('Not enough coins to unlock the island.','warn');state.coins-=ISLANDS[i].unlock;state.unlocked[i]=true;if(i==='wind')addDog('wind','water',false,true);switchIsland(i);closePanel();save();render();toast(`${ISLANDS[i].name} unlocked!`,'good')}
function collect(d){syncEconomy();let v=Math.floor(d.pending);if(v<1)return toast('Your dog is still collecting coins.');d.pending-=v;state.coins+=v;state.daily.coins+=v;state.stats.totalCoins+=v;xp(Math.min(80,v/30+4));save();sfx('coin');renderStats();toast(`+${fmt(v)} coins!`,'good')}
function collectAll(){syncEconomy();let n=0;for(const d of dogsOn()){let v=Math.floor(d.pending);d.pending-=v;n+=v}if(n<=0)return toast('More coins are being produced!');state.coins+=n;state.daily.coins+=n;state.stats.totalCoins+=n;xp(Math.min(130,n/35+8));save();sfx('coin');renderStats();toast(`Collected ${fmt(n)} coins!`,'good')}
function feed(d){if(d.level>=20)return toast('Level 20 is the maximum.');let cost=Math.floor(22*Math.pow(1.39,d.level-1));if(state.treats<cost)return toast(`Bake more treats: need ${fmt(cost)}.`,'warn');state.treats-=cost;d.level++;xp(20+d.level*3);state.stats.totalFeeds++;state.daily.feeds++;save();sfx('egg');render();openPanel('dog',d.uid)}
function sell(d){if(!d)return;const worth=(spec(d.type).myth?35000:spec(d.type).box?220000:spec(d.type).seasonal?25000:spec(d.type).exclusive?12000:Math.floor(150*Math.pow(3,tier(d.type)-1)))*(d.rare?3:1)*d.level; if(!confirm(`Sell ${d.rare?'Rare ':''}${spec(d.type).name} (Lv ${d.level}) for ${fmt(worth)} coins? This cannot be undone.`))return;state.dogs=state.dogs.filter(x=>x.uid!==d.uid);state.coins+=worth;audio.refreshMix();closePanel();save();render();toast(`Sold for ${fmt(worth)} coins.`,'good')}
function castle(){const i=current(),c=state.castle[i],idx=CASTLES.indexOf(c);if(idx===-1||idx>=CASTLE_PRICES.length)return toast('Castle already at the maximum capacity.');let cost=CASTLE_PRICES[idx];if(state.coins<cost)return toast(`Castle expansion costs ${fmt(cost)} coins.`,'warn');state.coins-=cost;state.castle[i]=CASTLES[idx+1];xp(250);save();render();openPanel('structures');toast(`Castle upgraded to ${state.castle[i]} spaces!`,'good')}
function buySingle(t){if(!ISLANDS[current()].elements.includes(t))return;if(dogsOn().length>=state.castle[current()])return toast('Expand your castle first.','warn');let cost=spec(t).price;if(state.coins<cost)return toast(`Need ${fmt(cost)} coins.`,'warn');state.coins-=cost;addDog(current(),t);save();render();openPanel('market')}
function activeTorches(i=current()){return state.structures[i].lit.filter(t=>t>Date.now()).length}
function odds(i=current()){let torches=activeTorches(i);return {myth:Math.min(.2,.05+.015*torches),rare:Math.min(.19,.04+.015*torches)}}
// Jinglepup has its OWN Rare chance: 15% base, +2 percentage points per lit Ice torch, up to 35%.
// This roll is conditional on the normal 12% Jinglepup seasonal breeding success.
function jinglepupRareOdds(i='ice'){return Math.min(.35,.15+.02*activeTorches(i))}
function eggSeconds(t,rare){if(t==='icemyth'&&rare)return 4*3600;if(t==='jinglepup'&&rare)return 3.5*3600;if(t==='jinglepup')return 3*3600;if(spec(t).myth)return 3*3600;if(rare)return tier(t)>=3?3*3600:tier(t)===2?2.25*3600:1.5*3600;return tier(t)>=3?1.75*3600:tier(t)===2?45*60:15*60}
function combo(i,a,b){const union=[...new Set([...spec(a.type).els,...spec(b.type).els])].filter(x=>ISLANDS[i].elements.some(e=>e.toLowerCase()===x.toLowerCase())).sort().join('+');return BASE[i].find(t=>!spec(t).myth&&spec(t).els.sort().join('+')===union)||null}
function breed(){let a=dogBy(view.parentA),b=dogBy(view.parentB),i=current();if(!a||!b||a.uid===b.uid||a.island!==i||b.island!==i)return toast('Choose two different parents from this island.','warn');if(state.incubators[i])return openPanel('nursery');if(spec(a.type).box||spec(b.type).box||spec(a.type).exclusive||spec(b.type).exclusive||spec(a.type).seasonal||spec(b.type).seasonal||spec(a.type).myth||spec(b.type).myth)return toast('Only regular element dogs can breed.','warn');let cost=1000*(tier(a.type)+tier(b.type)),trip=(tier(a.type)===2&&tier(b.type)===3)||(tier(b.type)===2&&tier(a.type)===3),target=null;
 const winter=i==='ice'&&seasonalNow()&&[a.type,b.type].includes('cold')&&[a.type,b.type].includes('icetriple');
 if(winter&&Math.random()<.12)target='jinglepup';
 if(!target&&trip&&Math.random()<odds(i).myth)target=BASE[i][7];
 if(!target)target=combo(i,a,b)||(trip?BASE[i][6]:a.type);
 if(state.coins<cost)return toast(`Breeding fee: ${fmt(cost)} coins.`,'warn');state.coins-=cost;
 // Jinglepup is the exclusive exception to the standard Rare odds; all other dogs retain their own original rates.
 let rare=Math.random()<(target==='jinglepup'?jinglepupRareOdds(i):odds(i).rare);
 const sec=eggSeconds(target,rare),now=Date.now();state.incubators[i]={island:i,type:target,rare,started:now,ready:now+sec*1000,duration:sec};xp(60);save();sfx('egg');openPanel('nursery');toast('Breeding complete. Your egg is incubating!','good')}
function speedEgg(){const e=state.incubators[current()];if(!e)return;const rem=e.ready-Date.now(),gems=Math.ceil(rem/3600000);if(gems<=0)return toast('Egg is ready to hatch.');if(state.gems<gems)return toast(`Need ${gems} gems to finish now.`,'warn');state.gems-=gems;e.ready=Date.now()-1;save();openPanel('nursery');toast(`Egg sped up for ${gems} gems.`,'good')}
function hatch(){let i=current(),e=state.incubators[i];if(!e)return;if(Date.now()<e.ready)return toast('The egg is not ready yet.','warn');if(dogsOn().length>=state.castle[i])return toast('Castle full. Expand or sell a dog.','warn');state.incubators[i]=null;const d=addDog(i,e.type,e.rare);if(!d)return;state.stats.totalHatches++;state.daily.hatches++;save();render();if(state.discovered.includes(collectionKey(i,e.type,e.rare))&&$('discoveryOverlay').classList.contains('hidden'))openPanel('dog',d.uid)}
function buyBakery(){const i=current(),st=state.structures[i],cost=5000*Math.pow(4,st.bakeries);if(st.bakeries>=3)return toast('Maximum of three bakeries per island.');if(state.coins<cost)return toast(`Need ${fmt(cost)} coins.`,'warn');state.coins-=cost;st.bakeries++;xp(120);save();render();openPanel('bakery')}
function bake(which){let i=current(),st=state.structures[i],r=BAKES[Number(which)];if(!r)return;if(st.bakeries<1)return toast('Build a bakery first.','warn');if(st.jobs.length>=st.bakeries)return toast('All bakeries are busy.','warn');if(state.coins<r.coins)return toast(`Need ${fmt(r.coins)} coins.`,'warn');state.coins-=r.coins;st.jobs.push({tier:+which,ready:Date.now()+r.time*1000});save();renderStats();openPanel('bakery');toast(`${r.name} started!`,'good')}
function claimBake(){const st=state.structures[current()];let done=st.jobs.filter(j=>j.ready<=Date.now());if(!done.length)return toast('Treats are still baking.');let total=done.reduce((a,j)=>a+BAKES[j.tier].treats,0);state.treats+=total;st.jobs=st.jobs.filter(j=>j.ready>Date.now());save();sfx('coin');renderStats();openPanel('bakery');toast(`Collected ${fmt(total)} treats!`,'good')}
function buildTorch(){let st=state.structures[current()];if(st.torches>=10)return toast('All ten torches are built.');const cost=12000+st.torches*8500;if(state.coins<cost)return toast(`Need ${fmt(cost)} coins.`,'warn');state.coins-=cost;st.torches++;save();openPanel('torches')}
function lightTorch(){let st=state.structures[current()];if(activeTorches()>=st.torches)return toast('Build another torch first.');if(state.coins<3500)return toast('Lighting a torch costs 3,500 coins.','warn');state.coins-=3500;st.lit=st.lit.filter(x=>x>Date.now());st.lit.push(Date.now()+4*3600*1000);save();openPanel('torches');toast('Torch lit for 4 hours! Rare and Mythical chances increased.','good')}
function upgradeStructure(kind){let st=state.structures[current()],lv=st[kind];if(lv>=5)return toast('Already fully upgraded.');const cost=(kind==='vault'?9000:12000)*Math.pow(3,lv);if(state.coins<cost)return toast(`Need ${fmt(cost)} coins.`,'warn');state.coins-=cost;st[kind]++;save();openPanel('structures');toast(`${kind==='vault'?'Coin Vault':'Song Monument'} upgraded!`,'good')}
function buyBox(rare){let s=state.boxes[current()],k=rare?'rare':'common',cost=rare?950000:210000;if(s[k])return toast('You already have a dormant Howltron of this rarity.');if(state.coins<cost)return toast(`Need ${fmt(cost)} coins.`,'warn');state.coins-=cost;s[k]=true;save();openPanel('howltron');toast(`${rare?'Rare ':''}Howltron shell purchased!`,'good')}
function activateBox(rare){const i=current(),k=rare?'rare':'common';if(!state.boxes[i][k])return;const picked=[];for(const t of BASE[i]){const d=dogsOn(i).find(d=>d.type===t&&d.rare===rare&&!picked.includes(d));if(!d)return toast(`Still need ${rare?'Rare ':''}${spec(t).name}. Mythicals count!`,'warn');picked.push(d)}if(!confirm(`Activate ${rare?'Rare ':''}Howltron? This permanently consumes eight ${rare?'Rare ':''}dogs, INCLUDING your ${rare?'Rare ':''}Mythical.`))return;const used=new Set(picked.map(d=>d.uid));state.dogs=state.dogs.filter(d=>!used.has(d.uid));state.boxes[i][k]=false;grant(i,'howltron',rare);audio.refreshMix();save();render();if($('discoveryOverlay').classList.contains('hidden'))openPanel('howltron')}
function placeStored(idx){const dog=state.inventory[Number(idx)];if(!dog)return;if(dogsOn(dog.island).length>=state.castle[dog.island])return toast('That island needs more castle space.','warn');state.inventory.splice(Number(idx),1);addDog(dog.island,dog.type,dog.rare);save();render();if($('discoveryOverlay').classList.contains('hidden'))openPanel('storage')}
// The wheel and scratch ticket can award species unavailable from breeding or the shop.
function randomPrize(kind){let roll=Math.random();if(kind==='wheel'){
 if(roll<.035)return {dog:'luckypaw',island:current(),rare:false};
 if(roll<.052)return {dog:BASE[current()][Math.floor(Math.random()*8)],island:current(),rare:true};
 if(roll<.27)return {treats:1000};if(roll<.56)return {coins:10000};if(roll<.78)return {gems:1};if(roll<.94)return {coins:35000};return {gems:5};}
 if(roll<.075)return {dog:'scratchpaw',island:current(),rare:false};
 if(roll<.11)return {dog:BASE[current()][Math.floor(Math.random()*8)],island:current(),rare:true};
 if(roll<.35)return {coins:32000};if(roll<.68)return {treats:4000};if(roll<.92)return {gems:3};return {gems:10};}
function prizeDesc(p){return p.dog?`${p.rare?'Rare ':''}${spec(p.dog).name} — ${ISLANDS[p.island].name}`:Object.entries(p).map(([k,v])=>`${fmt(v)} ${k}`).join(', ')}
function award(p){if(p.dog){grant(p.island,p.dog,p.rare)}else{for(const [k,v] of Object.entries(p))state[k]+=v;renderStats();toast(`You won ${prizeDesc(p)}!`,'good')}save()}
function spin(){if(spinning)return;let free=!state.daily.wheel;if(!free&&state.gems<2)return toast('Another spin costs 2 gems.','warn');if(!free)state.gems-=2;else state.daily.wheel=true;spinning=true;state.stats.totalSpins++;let prize=randomPrize('wheel');save();const b=$('spinWheelArt');if(b){b.style.transform='rotate(1480deg)';b.style.transition='transform 2.4s cubic-bezier(.15,.75,.15,1)'}setTimeout(()=>{spinning=false;award(prize);openPanel('wheel')},2450);toast('The wheel is spinning…','good')}
function buyScratch(){if(state.pendingScratch)return openPanel('ticket');let free=!state.daily.ticket;if(!free&&state.gems<5)return toast('Another ticket costs 5 gems.','warn');if(!free)state.gems-=5;else state.daily.ticket=true;state.pendingScratch=randomPrize('ticket');save();openPanel('ticket');initScratch();}
function claimScratch(){if(!state.pendingScratch)return;const prize=state.pendingScratch;state.pendingScratch=null;award(prize);openPanel('ticket')}
function initScratch(){const canvas=$('scratchCanvas');if(!canvas||!state.pendingScratch)return;let ctx=canvas.getContext('2d');ctx.globalCompositeOperation='source-over';let grad=ctx.createLinearGradient(0,0,400,0);grad.addColorStop(0,'#f0b0ee');grad.addColorStop(.5,'#64499e');grad.addColorStop(1,'#f8df9e');ctx.fillStyle=grad;ctx.fillRect(0,0,400,145);ctx.fillStyle='#fff';ctx.textAlign='center';ctx.font='bold 20px Trebuchet MS';ctx.fillText('SCRATCH TO REVEAL',200,80);ctx.globalCompositeOperation='destination-out';let active=false,steps=0;
 function scratch(e){const box=canvas.getBoundingClientRect(),x=(e.clientX-box.left)/box.width*400,y=(e.clientY-box.top)/box.height*145;ctx.beginPath();ctx.arc(x,y,22,0,Math.PI*2);ctx.fill();steps++;if(steps>24){canvas.style.opacity='0';setTimeout(claimScratch,300)}}
 canvas.addEventListener('pointerdown',e=>{active=true;canvas.setPointerCapture(e.pointerId);scratch(e)});canvas.addEventListener('pointermove',e=>{if(active)scratch(e)});canvas.addEventListener('pointerup',()=>active=false);}
const GOALS=[{id:'hatch',title:'First Harmony',desc:'Hatch a new dog.',ok:()=>state.stats.totalHatches>=1,reward:{coins:1600}},{id:'collector',title:'The Collector',desc:'Discover twelve different dog entries.',ok:()=>state.discovered.length>=12,reward:{gems:8}},{id:'music',title:'The Ensemble',desc:'Have eight dogs on one island.',ok:()=>keys.some(i=>dogsOn(i).length>=8),reward:{coins:30000}},{id:'rare',title:'Rare Find',desc:'Discover your first Rare dog.',ok:()=>state.dogs.some(d=>d.rare),reward:{gems:10}},{id:'myth',title:'Mythical Miracle',desc:'Discover your first Mythical.',ok:()=>state.dogs.some(d=>spec(d.type).myth),reward:{gems:12}},{id:'sky',title:'Cloud Rider',desc:'Unlock Wind Island.',ok:()=>state.unlocked.wind,reward:{gems:6}},{id:'box',title:'Powered Up',desc:'Activate a Howltron.',ok:()=>state.dogs.some(d=>d.type==='howltron'),reward:{gems:20}}];
const DAILY=[{id:'coins',title:'Collect Coins',target:5000,metric:()=>state.daily.coins,reward:{coins:4000}},{id:'feeds',title:'Feed Three Dogs',target:3,metric:()=>state.daily.feeds,reward:{treats:250}},{id:'hatches',title:'Hatch a Dog',target:1,metric:()=>state.daily.hatches,reward:{gems:1}}];
function earn(r){for(const[k,v]of Object.entries(r))state[k]+=v;sfx('egg')}
function claimGoal(id,daily=false){let g=(daily?DAILY:GOALS).find(x=>x.id===id);if(!g)return;const records=daily?state.daily.claimed:state.achievements;if(records.includes(id)||!(daily?g.metric()>=g.target:g.ok()))return;records.push(id);earn(g.reward);save();renderStats();openPanel('goals');toast(`Reward claimed! ${Object.entries(g.reward).map(([a,b])=>fmt(b)+' '+a).join('')}`,'good')}
function readyGoal(){return GOALS.some(x=>x.ok()&&!state.achievements.includes(x.id))||DAILY.some(x=>x.metric()>=x.target&&!state.daily.claimed.includes(x.id))}
function card(t,i,rarity=false){const found=state.discovered.includes(collectionKey(i,t,rarity));return `<div class="dog-card ${found?'':'locked'}"><img loading="lazy" src="${sprite(t,rarity)}" alt="${found?spec(t).name:'Undiscovered dog'}"><strong>${found?(rarity?'Rare ':'')+spec(t).name:'Undiscovered'}</strong><small>${found?spec(t).role:'???'}</small></div>`}
function pill(title,action,arg='',css=''){return `<button class="pill-btn ${css}" data-action="${action}" data-arg="${arg}">${title}</button>`}
function panelHeading(t,eyebrow='THE MUSIC NEVER ENDS'){$('modalTitle').textContent=t;$('modalEyebrow').textContent=eyebrow}
function openPanel(name,id){view.panel=name;view.selected=id||null;$('modalHost').classList.remove('hidden');renderPanel();$('modalClose').focus({preventScroll:true})}
function closePanel(){view.panel=null;view.selected=null;$('modalHost').classList.add('hidden')}
function renderPanel(){if(!view.panel)return;let i=current(),p=view.panel,html='';const st=state.structures[i];
 if(p==='islands'){
 panelHeading('Explore the Islands','THREE ORIGINAL SONGS');html=`<p class="modal-subtitle">A new island means new songs, breeds and more places for your collection to grow. Unlock islands with coins earned from your dogs.</p><div class="three-col">${keys.map(k=>`<div class="item-card island-card ${i===k?'selected':''}"><img src="bg-${k}.webp" style="width:100%;height:115px;object-fit:cover;border-radius:11px" alt="${ISLANDS[k].name}"><h3>${ISLANDS[k].name}</h3><p>${ISLANDS[k].elements.join(' · ')}<br>${stamp(SCORE[k].duration)} complete song</p>${state.unlocked[k]?pill(k===i?'Visiting now':'Travel to island','island',k,k===i?'ghost':'blue'):pill('Unlock for '+fmt(ISLANDS[k].unlock)+' coins','unlock',k,'blue')}</div>`).join('')}</div>`;
 }else if(p==='breed'){
 panelHeading('Breeding Garden','A LONGER JOURNEY TO LEGENDARY VOICES');let ds=dogsOn().filter(d=>!spec(d.type).myth&&!spec(d.type).box&&!spec(d.type).seasonal&&!spec(d.type).exclusive);
 if(!ds.some(d=>d.uid===view.parentA))view.parentA=ds[0]?.uid||null;if(!ds.some(d=>d.uid===view.parentB)||view.parentA===view.parentB)view.parentB=ds.find(d=>d.uid!==view.parentA)?.uid||null;
 let a=dogBy(view.parentA),b=dogBy(view.parentB);const op=ds.map(d=>`<option value="${d.uid}">${d.rare?'Rare ':''}${spec(d.type).name} · Lv ${d.level}</option>`).join('');let cost=a&&b?1000*(tier(a.type)+tier(b.type)):0,odd=odds();
 html=`<p class="modal-subtitle">Breeding is now a genuine journey. Single + single creates doubles; adding a single to a double makes triples. <b>Double + triple has a ${Math.round(odd.myth*1000)/10}% chance of a Mythical</b>. Rare eggs have a separate ${Math.round(odd.rare*1000)/10}% roll.</p>${ds.length<2?'<div class="warn-note">Adopt at least two different dogs from the Market.</div>':`<div class="two-col"><div><label class="field-label">First dog</label><select id="parentA" class="select-field">${op}</select></div><div><label class="field-label">Second dog</label><select id="parentB" class="select-field">${op}</select></div></div><div class="good-note">Breeding fee: ${fmt(cost)} coins · Torches lit: ${activeTorches()} / ${st.torches}<br>Mythical base: 5%; Rare base: 4%. No guaranteed Mythical pity timer.</div><div class="action-row">${pill('Breed · '+fmt(cost)+' coins','breed','','blue')}${pill('Light Wishing Torches','open','torches','ghost')}</div>`}`;
 if(i==='ice')html+=`<div class="warn-note"><b>Ice Seasonal:</b> Cold + Glacierhorn can yield Jinglepup (12%) during Dec 15–30 or Thu 11 PM–Fri 8 AM Eastern. <b>Rare Jinglepup alone has a special ${(jinglepupRareOdds(i)*100).toFixed(0)}% Rare-form roll</b> (15% base, +2% per lit torch, maximum 35%). All other Rares use normal odds. <b>${seasonalNow()?'AVAILABLE NOW':'CURRENTLY UNAVAILABLE'}</b>.</div>`;
 }else if(p==='nursery'){
 panelHeading('The Nursery','THE LONG ROAD TO A NEW SONG');let e=state.incubators[i];if(!e)html=`<div class="egg-showcase"><div class="large-egg"></div><h3>No eggs are incubating</h3><p class="modal-subtitle">The nursery is free. Breed two dogs to fill it.</p>${pill('Visit Breeding','open','breed','blue')}</div>`;
 else{const remaining=Math.max(0,(e.ready-Date.now())/1000),cost=Math.ceil(remaining/3600),pct=Math.max(0,100*(1-remaining/e.duration));html=`<div class="egg-showcase"><div class="large-egg ${spec(e.type).myth?'myth':''}"></div><h3>${remaining<=0?'An egg is ready to hatch!':'A new melody is forming…'}</h3><p class="modal-subtitle">${e.rare?'Rare ':'Normal '}egg · ${remaining<=0?'Ready now!':duration(remaining)+' remaining'}</p><div class="progress-outer"><div class="progress-inner" style="width:${pct}%"></div></div><div class="action-row">${remaining<=0?pill('Hatch now','hatch','','blue'):pill(`Speed up • ${cost} gem${cost===1?'':'s'}`,'speed','','blue')}</div><p class="modal-subtitle">One gem per remaining hour (rounded up), never over four gems. Rare Ice Mythical: 4h. Rare Ice Seasonal: 3h 30m.</p></div>`}
 }else if(p==='collection'){
 panelHeading('The Complete Collection','COMMONS · RARES · SPECIALS');const total=62;html=`<p class="modal-subtitle">Discovered <b>${state.discovered.length} / ${total}</b> collectible entries. Rares are collectible variants with distinct gem-encrusted outfits and improved coin production.</p>`;
 for(const k of keys){html+=`<h3 class="collection-section">${ISLANDS[k].name} · Commons & Mythicals</h3><div class="card-grid">${BASE[k].map(t=>card(t,k)).join('')}</div><h3 class="collection-section">${ISLANDS[k].name} · Rares</h3><div class="card-grid">${BASE[k].map(t=>card(t,k,true)).join('')}</div><h3 class="collection-section">Special Discoveries</h3><div class="card-grid">${EXTRA[k].flatMap(t=>t==='jinglepup'?[card(t,k),card(t,k,true)]:t==='howltron'?[card(t,k),card(t,k,true)]:[card(t,k)]).join('')}</div>`;}
 }else if(p==='market'){
 panelHeading('The Market','BETTER THINGS TAKE MORE WORK');html=`<p class="modal-subtitle">Buy basic dogs for coins, then breed to unlock the others. Rares, Mythicals, Seasonals and prize-exclusive dogs cannot be bought here.</p><div class="three-col">${ISLANDS[i].elements.map(t=>`<div class="item-card"><figure><img src="${sprite(t)}" alt="${spec(t).name}"></figure><h3>${spec(t).name}</h3><p>${spec(t).role}</p><span class="cost">${fmt(spec(t).price)} coins</span>${pill('Adopt','buy',t,'blue')}</div>`).join('')}</div><div class="section-separator"></div><h3>Expensive upgrades</h3><div class="three-col"><div class="item-card"><h3>Castle Expansion</h3><p>Room for ${state.castle[i]} dogs; maximum 64.</p>${pill('Upgrade Castle','castle','','blue')}</div><div class="item-card"><h3>Gem Exchange</h3><p>10 gems for 65,000 coins. Expensive but attainable through earnings.</p>${pill('Exchange 65,000 coins','gems','','ghost')}</div><div class="item-card"><h3>Storage</h3><p>Retrieve dogs you won while your castle was full.</p>${pill('Open Storage','open','storage','ghost')}</div></div>`;
 }else if(p==='dog'){
 let d=dogBy(view.selected);if(!d){closePanel();return}let t=spec(d.type),feedCost=Math.floor(22*Math.pow(1.39,d.level-1));panelHeading((d.rare?'Rare ':'')+t.name,t.myth?'MYTHICAL':t.seasonal?'SEASONAL':t.exclusive?'EXCLUSIVE':t.box?'POWERED LEGEND':'MUSICAL DOG');html=`<div class="dog-detail-layout"><div><img src="${sprite(d.type,d.rare)}" class="dog-portrait" alt="${t.name}"></div><div><p class="modal-subtitle">${t.role}. ${d.rare?'Extraordinary rare edition with enhanced earnings.':'An original member of your island orchestra.'}</p><div class="dog-info-grid"><div><small>LEVEL</small><strong>${d.level}/20</strong></div><div><small>PERFORMANCE</small><strong>${t.role}</strong></div><div><small>COIN RATE</small><strong>${rate(d).toFixed(2)}/second</strong></div><div><small>UNCLAIMED</small><strong>${fmt(d.pending)}</strong></div></div><div class="action-row">${pill('Collect '+fmt(d.pending),'collect',d.uid,'blue')}${pill('Feed '+(d.level===20?'MAX':fmt(feedCost)+' treats'),'feed',d.uid,'')}</div><div class="property-label"><span>Individual volume</span><strong id="dogVolumeReadout">${d.volume}%</strong></div><input type="range" class="range" id="dogVolume" min="0" max="2000" step="10" value="${d.volume}"><div class="action-row">${pill(d.muted?'Unmute':'Mute','muteDog',d.uid,'ghost')}${pill('Sell dog','sell',d.uid,'danger')}${pill('Close','close','','ghost')}</div></div></div>`;
 }else if(p==='bakery'){
 panelHeading('Island Bakeries','FRESH TREATS ARE WORTH THE WAIT');const ready=st.jobs.filter(j=>j.ready<=Date.now());html=`<p class="modal-subtitle">Bake treats to level up your dogs and increase their coin output. Bakeries work while you are away. Build up to three for parallel batches.</p><div class="good-note">${st.bakeries} / 3 bakeries built · ${st.jobs.length} / ${st.bakeries} ovens working · ${ready.length} batches ready</div><div class="action-row">${pill(`Build bakery · ${fmt(5000*Math.pow(4,st.bakeries))} coins`,'buyBakery','','blue')}${pill('Collect completed treats','claimBake','','ghost')}</div><h3>Choose a baking batch</h3><div class="two-col">${BAKES.map((x,j)=>`<div class="item-card"><h3>${x.name}</h3><p>${duration(x.time)} baking time<br>Produces ${fmt(x.treats)} treats</p><span class="cost">${fmt(x.coins)} coins</span>${pill('Start Baking','bake',j,'blue')}</div>`).join('')}</div><h3>Current ovens</h3>${st.jobs.length?st.jobs.map((j,n)=>`<div class="achievement-card"><strong>Oven ${n+1} · ${BAKES[j.tier].name}</strong><p>${j.ready<=Date.now()?'READY':duration((j.ready-Date.now())/1000)+' left'}</p></div>`).join(''):'<p class="modal-subtitle">No batches cooking yet.</p>'}`;
 }else if(p==='structures'){
 panelHeading('Structures & Castle','BUILD A BIGGER MUSICAL WORLD');let next=CASTLE_PRICES[CASTLES.indexOf(state.castle[i])];html=`<p class="modal-subtitle">Permanent structures make coins worthwhile. Huge castles hold both Common and Rare collections, and your special dogs, too.</p><div class="three-col"><div class="item-card"><h3>Great Castle</h3><p>${state.castle[i]} / 64 spaces. Expand through ${CASTLES.join(' → ')} spaces.</p><span class="cost">${next?fmt(next)+' coins':'MAXIMUM'}</span>${pill('Expand Castle','castle','','blue')}</div><div class="item-card"><h3>Coin Vault · Lv ${st.vault}/5</h3><p>Expands banks and raises coin production by 7% per level.</p><span class="cost">${fmt(9000*Math.pow(3,st.vault))} coins</span>${pill('Upgrade Vault','upgrade','vault','ghost')}</div><div class="item-card"><h3>Song Monument · Lv ${st.monument}/5</h3><p>Boosts experience gained from playing and feeding.</p><span class="cost">${fmt(12000*Math.pow(3,st.monument))} coins</span>${pill('Upgrade Monument','upgrade','monument','ghost')}</div><div class="item-card"><h3>Bakeries</h3><p>Make larger treat batches and bake with multiple ovens.</p>${pill('Visit Bakeries','open','bakery','blue')}</div><div class="item-card"><h3>Wishing Torches</h3><p>Raise Rare and Mythical breeding chances.</p>${pill('Visit Torches','open','torches','blue')}</div><div class="item-card"><h3>Howltron Workshop</h3><p>Consume a full collection to energize a mighty performer.</p>${pill('Visit Workshop','open','howltron','blue')}</div></div>`;
 }else if(p==='torches'){
 panelHeading('Wishing Torches','BECAUSE RARE DISCOVERIES TAKE LUCK');const chance=odds();html=`<p class="modal-subtitle">Build up to ten wishing torches per island. Lighting one costs 3,500 coins and lasts 4 hours. Each burning torch adds 1.5 percentage points to both chances.</p><div class="torch-summary"><div><span>TORCHES BUILT</span><strong>${st.torches}/10</strong></div><div><span>BURNING NOW</span><strong>${activeTorches()}/10</strong></div><div><span>MYTHICAL CHANCE</span><strong>${(chance.myth*100).toFixed(1)}%</strong></div><div><span>RARE CHANCE</span><strong>${(chance.rare*100).toFixed(1)}%</strong></div></div><div class="torch-visual">${Array.from({length:10},(_,x)=>`<span class="torch ${x<activeTorches()?'burning':x<st.torches?'built':''}"></span>`).join('')}</div>${i==='ice'?`<div class="good-note"><b>Rare Jinglepup SPECIAL CHANCE:</b> ${(jinglepupRareOdds(i)*100).toFixed(0)}% if a Jinglepup is bred (15% base → 35% with 10 lit torches). All other Rares remain at ${(chance.rare*100).toFixed(1)}%.</div>`:''}<div class="action-row">${pill('Build torch · '+fmt(12000+st.torches*8500)+' coins','buildTorch','','blue')}${pill('Light for 3,500 coins','lightTorch','','')}</div><p class="modal-subtitle">Base Mythical chance is exactly <b>5%</b> without torches. Base Rare roll is 4%. A Rare Mythical must succeed in both rolls.</p>`;
 }else if(p==='wheel'){
 panelHeading('Paw Spin Wheel','A FREE SPIN EVERY NEW YORK DAY');html=`<p class="modal-subtitle">One free spin each day; additional spins cost exactly <b>2 gems</b>. The exclusive <b>Luckypaw</b> cannot be bred or purchased in the Market.</p><div class="game-of-chance"><div id="spinWheelArt" class="prize-wheel"><span class="wheel-center">PAW SPIN</span></div><p class="cost">${state.daily.wheel?'Additional spin: 2 gems':'FREE DAILY SPIN AVAILABLE'}</p>${pill(state.daily.wheel?'Spin • 2 gems':'FREE SPIN','spin','','blue')}</div><div class="good-note">Possible rewards: coins, treats, gems, Rares and the exclusive Luckypaw.</div>`;
 }else if(p==='ticket'){
 panelHeading('Scratch Tickets','A FREE TICKET EVERY NEW YORK DAY');html=`<p class="modal-subtitle">One free ticket each day; additional tickets cost exactly <b>5 gems</b>. Exclusive <b>Scratchpaw</b> appears only here.</p><div class="game-of-chance"><div class="scratch-reveal"><div class="scratch-prize">${state.pendingScratch?prizeDesc(state.pendingScratch):'YOUR NEXT PRIZE?'}</div>${state.pendingScratch?'<canvas id="scratchCanvas" width="400" height="145" aria-label="Drag to scratch and reveal your prize"></canvas>':''}</div>${state.pendingScratch?'<p class="modal-subtitle">Rub over the card until it is revealed.</p>':pill(state.daily.ticket?'New Ticket • 5 gems':'FREE DAILY TICKET','scratch','','blue')}</div><div class="good-note">Possible rewards: gems, coins, treats, Rares and the exclusive Scratchpaw.</div>`;setTimeout(initScratch,0);
 }else if(p==='howltron'){
 panelHeading('The Howltron Workshop','THE ENTIRE COLLECTION POWERS THE SONG');html=`<p class="modal-subtitle">Buy a dormant Howltron, then feed it ONE of every base dog on this island. <b>Mythicals count.</b> The seasonal dog and Wheel/Ticket exclusives are excluded. Activating consumes all eight required dogs.</p><div class="two-col">${[false,true].map(rare=>{let k=rare?'rare':'common',shell=state.boxes[i][k],needed=BASE[i].filter(t=>!dogsOn().some(d=>d.type===t&&d.rare===rare));return `<div class="item-card"><img src="${sprite('howltron',rare)}" alt="${rare?'Rare ':''}Howltron" style="height:150px;width:100%;object-fit:contain"><h3>${rare?'Rare ':''}Howltron</h3><p>${shell?'SHELL PURCHASED':'Not yet purchased'} · ${8-needed.length}/8 required dogs available</p><p class="modal-subtitle">${BASE[i].map(t=>{let found=!needed.includes(t);return `<span class="tiny-species ${found?'ready':''}">${found?'✓':'·'} ${rare?'Rare ':''}${spec(t).name}</span>`}).join(' ')}</p><div class="action-row">${shell?pill('Activate by consuming all 8','activateBox',k,'blue'):pill('Buy shell · '+fmt(rare?950000:210000)+' coins','buyBox',k,'blue')}</div></div>`}).join('')}</div>`;
 }else if(p==='storage'){
 panelHeading('Dog Storage','REWARDS NEVER GET LOST');html=`<p class="modal-subtitle">Extra prize dogs go here if their island castle is full. Expand a castle to place them later.</p>${state.inventory.length?state.inventory.map((d,j)=>`<div class="achievement-card"><img src="${sprite(d.type,d.rare)}" style="width:68px;height:68px;object-fit:contain"><div><strong>${d.rare?'Rare ':''}${spec(d.type).name}</strong><p>${ISLANDS[d.island].name}</p></div>${pill('Place','placeStored',j,'blue')}</div>`).join(''):'<div class="good-note">Storage is empty.</div>'}`;
 }else if(p==='seasonal'){
 panelHeading('Ice Seasonal Festival','A RARE WINTER PERFORMANCE');html=`<div class="two-col"><div><img src="dog-jinglepup.webp" class="dog-portrait" alt="Jinglepup"><h3>Jinglepup</h3><p class="modal-subtitle">A festive Ice Island singer who performs warm bells and harmonies. Rare Jinglepup wears royal winter regalia.</p></div><div class="item-card"><h3>${seasonalNow()?'AVAILABLE NOW':'NOT CURRENTLY AVAILABLE'}</h3><p>Every December 15–30 (Eastern), and weekly Thursday 11 PM – Friday 8 AM Eastern, even outside December.</p><p>Ice breeding: Cold + Glacierhorn has a <b>12% seasonal chance</b> while active. <b>Rare Jinglepup is a special exception:</b> ${(jinglepupRareOdds(i)*100).toFixed(0)}% Rare-form chance after a successful Jinglepup result (15% with no lit torches, 35% with 10). That's ${(12*jinglepupRareOdds(i)).toFixed(2)}% overall per eligible breeding attempt for Rare Jinglepup.</p><p><b>Common Jinglepup:</b> 3h egg.<br><b>Rare Jinglepup:</b> 3h 30m egg.</p>${pill('Visit Ice Island','island','ice','blue')}</div></div>`;
 }else if(p==='goals'){
 panelHeading('Goals & Achievements','REWARD THE LONG-TERM GRIND');html=`<p class="modal-subtitle">Keep earning, breeding and developing your collection for extra resources.</p><h3>Daily Goals</h3>${DAILY.map(g=>{const claimed=state.daily.claimed.includes(g.id),ready=g.metric()>=g.target;return `<div class="achievement-card"><div><strong>${g.title}</strong><p>${Math.min(g.target,g.metric())}/${g.target} · ${Object.entries(g.reward).map(([k,v])=>fmt(v)+' '+k).join('')}</p></div>${claimed?'Claimed':ready?pill('Claim','claimDaily',g.id,'blue'):'In progress'}</div>`}).join('')}<h3>Long-term Goals</h3>${GOALS.map(g=>{let claimed=state.achievements.includes(g.id);return `<div class="achievement-card"><div><strong>${g.title}</strong><p>${g.desc}</p></div>${claimed?'Claimed':g.ok()?pill('Claim','claimGoal',g.id,'blue'):'In progress'}</div>`}).join('')}`;
 }else if(p==='settings'){
 panelHeading('Options & Save Data','MAKE THE WORLD YOUR OWN');html=`<p class="modal-subtitle">Settings and your entire collection autosave on this device. Back up before clearing the browser or switching computers.</p>${[['master','Master volume'],['music','Music volume'],['sfx','Sound effects']].map(([k,label])=>`<div class="setting-row"><span class="setting-name">${label}</span><input class="range setting-slider" data-setting="${k}" type="range" min="0" max="2000" value="${state.settings[k]}"><output id="setting-${k}">${state.settings[k]}%</output></div>`).join('')}<div class="warn-note">High amplification can be uncomfortable. Start with a comfortable headphone volume.</div><label style="display:flex;align-items:center;gap:9px;margin:19px 0"><input type="checkbox" id="reducedMotion" ${state.settings.reducedMotion?'checked':''}> Reduce decorative movement</label><div class="action-row">${pill('Export backup','export','','blue')}${pill('Import backup','import','','ghost')}${pill('Save now','save','','ghost')}${pill('Reset everything','reset','','danger')}</div>`;
 }else if(p==='help'){
 panelHeading('How to Play','FROM A PUP TO A SYMPHONY');html=`<div class="help-section"><h3>Unlock new islands</h3><p>Plant starts available. Earn coins to unlock Ice (25,000) and Wind (65,000). Wind introduces the Water element and a new 2:28 composition.</p></div><div class="help-section"><h3>Breeding takes time</h3><p>Combine singles, doubles, then triples. Double + triple gives exactly 5% base Mythical chance. Rares roll separately, starting at 4%. Exception: when Ice Island's Jinglepup is bred, its Rare-form chance is 15% base, rising to 35% with ten lit torches. Build and light Wishing Torches to improve both.</p></div><div class="help-section"><h3>Bakeries and structures</h3><p>Bake treats over time to level up performers. Spend coins on bakeries, larger castles, coin vaults, monuments, torches, and the Howltron workshop. High-end upgrades are expensive.</p></div><div class="help-section"><h3>Legendary Howltrons</h3><p>Common Howltron consumes a complete Common set, INCLUDING the Mythical. Rare Howltron consumes all eight Rares, including Rare Mythical. Seasonals and game-exclusive dogs are excluded.</p></div><div class="help-section"><h3>Special games and Seasonals</h3><p>One free Wheel spin and Scratch Ticket daily on New York time; extra attempts cost 2 and 5 gems. Both can give exclusive dogs. Ice Jinglepup appears Dec 15–30 or Thu 11 PM to Fri 8 AM Eastern.</p></div><div class="help-section"><h3>Saving and music</h3><p>Every island has a 1–3 minute original song and note-timed musical animations. Dogs play parts together and rest in their own sections. Export/import a save to keep data between devices.</p></div>`;
 }
 $('modalBody').innerHTML=html;
 if(p==='breed'){if($('parentA'))$('parentA').value=view.parentA||'';if($('parentB'))$('parentB').value=view.parentB||'';}
}
function handle(action,arg){switch(action){case 'open':openPanel(arg);break;case 'close':closePanel();break;case 'island':closePanel();switchIsland(arg);break;case 'unlock':buyUnlock(arg);break;case 'buy':buySingle(arg);break;case 'gems':if(state.coins<65000)toast('Need 65,000 coins.','warn');else{state.coins-=65000;state.gems+=10;save();renderStats();openPanel('market')}break;case 'collect':{let d=dogBy(arg);if(d)collect(d);break}case 'feed':{let d=dogBy(arg);if(d){feed(d);openPanel('dog',d.uid)}break}case 'sell':sell(dogBy(arg));break;case 'muteDog':{let d=dogBy(arg);if(d){d.muted=!d.muted;audio.refreshMix();save();render();openPanel('dog',d.uid)}break}case 'castle':castle();break;case 'breed':breed();break;case 'hatch':hatch();break;case 'speed':speedEgg();break;case 'buyBakery':buyBakery();break;case 'bake':bake(arg);break;case 'claimBake':claimBake();break;case 'buildTorch':buildTorch();break;case 'lightTorch':lightTorch();break;case 'upgrade':upgradeStructure(arg);break;case 'buyBox':buyBox(arg==='rare');break;case 'activateBox':activateBox(arg==='rare');break;case 'placeStored':placeStored(arg);break;case 'spin':spin();break;case 'scratch':buyScratch();break;case 'claimGoal':claimGoal(arg);break;case 'claimDaily':claimGoal(arg,true);break;case 'save':save();toast('Saved locally!','good');break;case 'export':exportSave();break;case 'import':$('importSaveFile').click();break;case 'reset':if(confirm('RESET ALL progress? Export your save first. This is irreversible without a backup.')){localStorage.removeItem(SAVEKEY);audio.pause();audio.setConcert(false);state=initial();for(const t of ['wind','stone','tech'])addDog('plant',t,false,true);lastTick=Date.now();audio.setIsland('plant');closePanel();save();render();toast('A new world begins!','good')}break;}}
function exportSave(){syncEconomy();save();const json=JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),blob=new Blob([json],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`MSD-expansion-save-${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2500);toast('Backup downloaded!','good')}
async function importSave(file){if(!file)return;try{if(file.size>2000000)throw Error('Save is too large.');const data=JSON.parse(await file.text());if(!data||![1,2].includes(data.version)||!Array.isArray(data.dogs))throw Error('Not an MSD save file.');if(!confirm('Import this save and replace current progress?'))return;localStorage.setItem(SAVEKEY,JSON.stringify(data));audio.pause();audio.buffers.clear();start();closePanel();render();toast('Save imported!','good')}catch(e){toast(`Import failed: ${e.message}`,'warn')}}
function dogHtml(d,index){let t=spec(d.type),s=dogsOn(d.island).length,scale=s>30?.70:s>20?.78:s>14?.88:1;return `<button class="dog ${d.muted?'is-muted':''} ${d.rare?'is-rare':''}" data-uid="${d.uid}" data-type="${d.type}" data-style="${t.style}" style="left:${d.x}%;top:${d.y}%;--aura:${t.color};--dogscale:${scale};z-index:${3+Math.round(d.y/10)}"><span class="dog-graphic"><span class="perform-glow"></span><span class="perform-floor"></span><img class="dog-img" draggable="false" src="${sprite(d.type,d.rare)}" alt="${d.rare?'Rare ':''}${t.name}">${mouth(d.type)}<span class="perform-waves"></span><span class="perform-stars"></span></span><span class="dog-name">${d.rare?'RARE ':''}${t.name}<span class="dog-level">Lv ${d.level}</span></span><span class="dog-coin ${d.pending<1?'hidden':''}">${fmt(d.pending)}</span></button>`}
function renderWorld(){const i=current(),a=ISLANDS[i],arr=dogsOn(i);$('worldArt').className=`world-art ${i}`;$('worldTitle').textContent=a.name;$('worldEyebrow').textContent=a.label;$('worldTagline').textContent=a.tag;$('headerSubtitle').textContent=a.name;$('barIsland').textContent=a.name.toUpperCase();$('songTitle').textContent=`${a.name} · ${a.song}`;$('songMeasure').textContent=`64 bars · ${SCORE[i].bpm} BPM`;
 for(const k of keys){let dot=$('dot'+k[0].toUpperCase()+k.slice(1));if(dot)dot.classList.toggle('active',k===i)}$('dogField').innerHTML=arr.map(dogHtml).join('')+(audio.concert?BASE[i].filter(t=>!arr.some(d=>d.type===t)).map((t,j)=>{let pos=SLOTS[(j+arr.length)%SLOTS.length];return `<div class="dog preview-dog" data-type="${t}" data-style="${spec(t).style}" style="left:${pos[0]}%;top:${pos[1]}%;--aura:${spec(t).color}"><span class="dog-graphic"><img class="dog-img" src="${sprite(t)}" alt="${spec(t).name} preview">${mouth(t)}<span class="perform-waves"></span></span><span class="dog-name">${spec(t).name} · Preview</span></div>`}).join(''):'');
 $('concertBtn').classList.toggle('active',audio.concert);$('concertText').textContent=audio.concert?'End full concert':'Hear full concert';$('worldNote').textContent=`Tap a dog for feeding, muting or selling. Drag to move. ${arr.length} / ${state.castle[i]} castle spaces.`;
 let b=$('structureStage');if(b)b.innerHTML=`<button data-panel="structures" class="stage-structure st-castle" title="Castle"><span class="st-turrets">${icon('castle')}</span><strong>Castle ${state.castle[i]}</strong></button><button data-panel="bakery" class="stage-structure st-bakery" title="Bakery"><span class="st-turrets">${icon('bone')}</span><strong>${state.structures[i].bakeries} Bakeries</strong></button><button data-panel="torches" class="stage-structure st-torch" title="Wishing Torches"><span class="st-turrets">${icon('star')}</span><strong>${activeTorches()} Lit</strong></button>`;
}
function renderStats(){const i=current(),arr=dogsOn(),amount=Math.floor(arr.reduce((a,d)=>a+d.pending,0));$('coinsText').textContent=fmt(state.coins);$('treatsText').textContent=fmt(state.treats);$('gemsText').textContent=fmt(state.gems);$('levelText').textContent='Level '+level();let cur=160*(level()-1)**2,next=160*level()**2;$('xpFill').style.width=Math.min(100,Math.max(0,(state.xp-cur)/(next-cur)*100))+'%';$('worldDogs').textContent=`${arr.length}/${state.castle[i]} dogs`;$('worldCapacity').textContent=`Castle ${state.castle[i]}`;$('pendingText').textContent=amount?'+'+fmt(amount):'';$('collectionCount').textContent=`${state.discovered.length} / 62`;$('eggBadge').classList.toggle('hidden',!state.incubators[i]);$('goalBadge').classList.toggle('hidden',!readyGoal());for(const d of arr){const el=document.querySelector(`[data-uid="${d.uid}"] .dog-coin`);if(el){el.textContent=fmt(d.pending);el.classList.toggle('hidden',d.pending<1)}}}
function renderAudio(){if(!state)return;$('playBtn').innerHTML=icon(audio.playing?'pause':'play');$('playBtn').setAttribute('aria-label',audio.playing?'Pause music':'Play music');$('soundBtn').innerHTML=icon(audio.muted?'mute':'sound');$('songTitle').textContent=ISLANDS[current()].song;$('trackTiming').textContent=`${stamp(audio.now())} / ${stamp(SCORE[current()].duration)}`;$('playbackStatus').textContent=audio.loading?'Preparing the orchestra…':audio.playing?(audio.concert?'Full eight-dog concert':'Your dogs are performing'):'Tap play to hear your island';}
function render(){renderWorld();renderStats();renderAudio()}
function bind(){
 $('enterBtn').addEventListener('click',()=>{$('splash').classList.add('hidden');$('game').classList.remove('hidden');render();sfx()});
 $('homeBtn').addEventListener('click',()=>{audio.pause();$('game').classList.add('hidden');$('splash').classList.remove('hidden');save()});
 document.addEventListener('click',e=>{let btn=e.target.closest('[data-panel]');if(btn&&!btn.disabled){openPanel(btn.dataset.panel);return}});
 $('settingsTop').addEventListener('click',()=>openPanel('settings'));$('openCollection').addEventListener('click',()=>openPanel('collection'));
 $('walletCoins').addEventListener('click',collectAll);$('walletTreats').addEventListener('click',()=>openPanel('bakery'));$('walletGems').addEventListener('click',()=>openPanel('wheel'));
 $('collectAllBtn').addEventListener('click',collectAll);
 $('concertBtn').addEventListener('click',async()=>{audio.setConcert(!audio.concert);renderWorld();if(!audio.playing&&!audio.loading)await audio.play();});
 $('prevIsland').addEventListener('click',()=>switchIsland(keys[(keys.indexOf(current())+keys.length-1)%keys.length]));$('nextIsland').addEventListener('click',()=>switchIsland(keys[(keys.indexOf(current())+1)%keys.length]));
 $('playBtn').addEventListener('click',()=>audio.toggle());$('restartBtn').addEventListener('click',()=>audio.restart());$('soundBtn').addEventListener('click',()=>audio.setMuted(!audio.muted));
 $('progress').addEventListener('input',e=>audio.seek(Number(e.target.value)/1000*audio.duration));
 $('modalClose').addEventListener('click',closePanel);$('modalShade').addEventListener('click',closePanel);
 $('modalBody').addEventListener('click',e=>{let btn=e.target.closest('[data-action]');if(btn&&!btn.disabled)handle(btn.dataset.action,btn.dataset.arg||'')});
 $('modalBody').addEventListener('change',e=>{if(e.target.id==='parentA'||e.target.id==='parentB'){view[e.target.id]=e.target.value;renderPanel()}else if(e.target.id==='reducedMotion'){state.settings.reducedMotion=e.target.checked;document.body.classList.toggle('reduced-motion',e.target.checked);save()}});
 $('modalBody').addEventListener('input',e=>{let t=e.target;if(t.id==='dogVolume'){let d=dogBy(view.selected);if(d){d.volume=+t.value;$('dogVolumeReadout').textContent=d.volume+'%';audio.refreshMix();save()}}else if(t.dataset.setting){state.settings[t.dataset.setting]=+t.value;$('setting-'+t.dataset.setting).textContent=t.value+'%';audio.setVolumes(state.settings.master,state.settings.music);save()}});
 $('importSaveFile').addEventListener('change',e=>{let f=e.target.files[0];e.target.value='';importSave(f)});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('discoveryOverlay').classList.contains('hidden'))$('discoveryOverlay').classList.add('hidden');else closePanel()}else if(e.code==='Space'&&!view.panel&&!$('game').classList.contains('hidden')&&!['INPUT','BUTTON','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();audio.toggle()}});
 document.addEventListener('visibilitychange',()=>{if(document.hidden){syncEconomy();save();if(audio.playing)audio.pause()}else{lastTick=state.lastAt;syncEconomy();renderStats()}});
 window.addEventListener('beforeunload',()=>{syncEconomy();save()});
 let stage=$('dogField');stage.addEventListener('pointerdown',e=>{let el=e.target.closest('.dog[data-uid]');if(!el||e.button>0)return;let d=dogBy(el.dataset.uid);if(!d)return;dragging={id:d.uid,pointer:e.pointerId,startX:e.clientX,startY:e.clientY,ix:d.x,iy:d.y,moved:false,el};el.setPointerCapture(e.pointerId);e.preventDefault()});
 stage.addEventListener('pointermove',e=>{let g=dragging;if(!g||g.pointer!==e.pointerId)return;let d=dogBy(g.id);if(!d)return;const dx=e.clientX-g.startX,dy=e.clientY-g.startY;if(Math.hypot(dx,dy)>9)g.moved=true;if(!g.moved)return;const rect=stage.getBoundingClientRect();d.x=Math.max(13,Math.min(91,g.ix+dx/rect.width*100));d.y=Math.max(40,Math.min(86,g.iy+dy/rect.height*100));g.el.style.left=d.x+'%';g.el.style.top=d.y+'%';g.el.classList.add('is-moving')});
 stage.addEventListener('pointerup',e=>{let g=dragging;if(!g||g.pointer!==e.pointerId)return;dragging=null;try{g.el.releasePointerCapture(e.pointerId)}catch(_){}g.el.classList.remove('is-moving');if(g.moved)save();else openPanel('dog',g.id)});
 stage.addEventListener('pointercancel',()=>{dragging=null;renderWorld()});
}
// Melody-accurate animation: performers visibly rest, hold notes, and move to instrument attacks.
function activeNote(notes,sec){if(!notes||!notes.length)return null;let lo=0,hi=notes.length-1,idx=-1;while(lo<=hi){let mid=(lo+hi)>>1;if(notes[mid].t<=sec){idx=mid;lo=mid+1}else hi=mid-1}for(let i=idx;i>=Math.max(0,idx-8);i--){let n=notes[i];if(sec>=n.t&&sec<n.t+n.d)return n}return null}
function frame(time){if(state&&!$('game').classList.contains('hidden')){let sec=audio.now(),sc=SCORE[current()];if(time-lastFrame>230){$('trackTiming').textContent=`${stamp(sec)} / ${stamp(sc.duration)}`;if(document.activeElement!==$('progress'))$('progress').value=1000*sec/sc.duration;$('worldSection').textContent=sc.sections[Math.min(sc.sections.length-1,Math.floor(sec/(sc.duration/sc.sections.length)))].title;lastFrame=time;}
 for(const el of document.querySelectorAll('#dogField .dog[data-type]')){const t=el.dataset.type,d=el.dataset.uid?dogBy(el.dataset.uid):null,active=audio.playing&&(audio.concert||d&&!d.muted&&d.volume>0),n=active?activeNote(sc.tracks[t],sec):null;el.classList.toggle('is-sounding',!!n);if(n){const phase=(sec-n.t)/Math.max(.01,n.d),style=spec(t).style;let lift=0,lean=0,scale=1;if(style==='voice'){lift=-3-3*Math.sin(phase*Math.PI);lean=-3*Math.sin(phase*Math.PI);scale=1.023+Math.sin(phase*Math.PI)*.035}else if(style==='bass'||style==='drum'){lift=phase<.2?2:0;scale=phase<.3?1.042:1}else if(style==='synth'){lift=-2;lean=Math.sin(phase*6.28)*1.7;scale=1.02}else if(style==='wind'){lift=-5*Math.sin(phase*Math.PI);lean=-4*Math.sin(phase*Math.PI);scale=1.025}else{lift=-2;lean=Math.sin(phase*Math.PI*2)*2;scale=1.024}el.style.setProperty('--lift',lift+'px');el.style.setProperty('--lean',lean+'deg');el.style.setProperty('--scale',scale);el.style.setProperty('--mouthScale',(1.12+Math.min(.42,n.v*.4)+.07*Math.sin(phase*Math.PI*3)).toFixed(2));const id=n.t+':'+n.n;if(el.dataset.note!==id){el.dataset.note=id;el.classList.remove('note-hit');void el.offsetWidth;el.classList.add('note-hit')}}else{el.dataset.note='';el.classList.remove('note-hit');el.style.setProperty('--lift','0px');el.style.setProperty('--lean','0deg');el.style.setProperty('--scale','1');el.style.setProperty('--mouthScale','1')}}}
 requestAnimationFrame(frame)}
function tick(){if(!state)return;syncEconomy();renderStats();if(['nursery','bakery','torches','seasonal'].includes(view.panel))renderPanel();save()}
function init(){start();bind();document.body.classList.toggle('reduced-motion',state.settings.reducedMotion);render();setInterval(tick,1800);requestAnimationFrame(frame);if('serviceWorker'in navigator&&['https:','http:'].includes(location.protocol))navigator.serviceWorker.register('sw.js').catch(()=>{});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();

/* iOS/iPadOS: protect game UI from native selection and long-press menus.
   Do not block text input or the game's custom pointer interactions. */
(function guardTouchUI(){
  const editable = el => !!(el && el.closest && el.closest('input, textarea, select, [contenteditable="true"]'));
  document.addEventListener('contextmenu',e=>{if(!editable(e.target))e.preventDefault()});
  document.addEventListener('selectstart',e=>{if(!editable(e.target))e.preventDefault()});
  document.addEventListener('dragstart',e=>{if(!editable(e.target))e.preventDefault()});
  document.addEventListener('dblclick',e=>{if(!editable(e.target))e.preventDefault()});
})();
